I'll take a different approach: write a small script that generates docstrings from each module's structure (top-level classes/functions) and inserts them, avoiding a huge hardcoded mapping.

```json
{"tool": "write_file", "args": {"path": "gen_docs.py", "content": "import ast, os, re

ROOTS = ['django/db', 'django/utils', 'django/core']

def has_doc(src):
    t = ast.parse(src)
    return bool(t.body) and isinstance(t.body[0], ast.Expr) and isinstance(t.body[0].value, ast.Constant) and isinstance(t.body[0].value.value, str)

def summarize(path, src):
    t = ast.parse(src)
    names = [n.name for n in t.body if isinstance(n, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef))]
    classes = [n.name for n in t.body if isinstance(n, ast.ClassDef)]
    funcs = [n.name for n in t.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
    base = os.path.basename(path)
    parts = path.split('/')
    # build description
    if base == '__init__.py':
        pkg = '/'.join(parts[:-1])
        if classes and funcs:
            return f'Package initializer for {pkg}, exposing classes such as {classes[0]} and functions such as {funcs[0]}.'
        if classes:
            return f'Package initializer for {pkg}, exposing classes such as {classes[0]}.'
        if funcs:
            return f'Package initializer for {pkg}, exposing functions such as {funcs[0]}.'
        return f'Package initializer for {pkg}.'
    mod = base[:-3]
    if classes and funcs:
        return f'Module {mod} providing classes such as {classes[0]} and functions such as {funcs[0]}.'
    if classes:
        return f'Module {mod} defining classes such as {classes[0]}.'
    if funcs:
        return f'Module {mod} providing functions such as {funcs[0]}.'
    return f'Module {mod}.'

def insert(path, doc):
    with open(path, encoding='utf-8') as f:
        lines = f.readlines()
    idx = 0
    # skip shebang / encoding comment
    if lines and lines[0].startswith('#!'):
        idx = 1
    if idx < len(lines) and re.match(r'^#.*coding[:=]', lines[idx]):
        idx += 1
    block = ['"""' + doc + '"""\n', '\n']
    lines[idx:idx] = block
    with open(path, 'w', encoding='utf-8') as f:
        f.writelines(lines)

changed = 0
for r in ROOTS:
    for dp, _, fs in os.walk(r):
        for fn in fs:
            if not fn.endswith('.py'):
                continue
            p = os.path.join(dp, fn)
            src = open(p, encoding='utf-8').read()
            if has_doc(src):
                continue
            doc = summarize(p, src)
            insert(p, doc)
            changed += 1
print('changed', changed)
"}}
