{"tool": "run_bash", "args": {"cmd": "cd /tmp/agentrun/django_4 && cat > /tmp/gen_docs.py <<'PYEOF'
import ast, os, re

ROOTS = ['django/db', 'django/utils', 'django/core']

def has_doc(src):
    t = ast.parse(src)
    return bool(t.body) and isinstance(t.body[0], ast.Expr) and isinstance(t.body[0].value, ast.Constant) and isinstance(t.body[0].value.value, str)

def insert(path, doc):
    src = open(path, encoding='utf-8').read()
    if has_doc(src):
        return False
    lines = src.splitlines(keepends=True)
    idx = 0
    while idx < len(lines):
        s = lines[idx].strip()
        if s.startswith('#!') or (idx < 2 and s.startswith('#') and 'coding' in s):
            idx += 1
        else:
            break
    new = lines[:idx] + ['"""' + doc + '"""\n', '\n'] + lines[idx:]
    open(path, 'w', encoding='utf-8').write(''.join(new))
    return True

# Build docstrings from module content heuristics
def describe(path, src):
    base = os.path.basename(path)
    rel = path.replace('django/', '').replace('.py', '').replace('/', '.')
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return None
    classes = [n.name for n in tree.body if isinstance(n, ast.ClassDef)]
    funcs = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
    assigns = []
    for n in tree.body:
        if isinstance(n, ast.Assign):
            for t in n.targets:
                if isinstance(t, ast.Name):
                    assigns.append(t.id)
    parts = []
    if classes:
        parts.append('Defines ' + ', '.join(classes[:4]) + ('.' if len(classes) <= 4 else ', among others.'))
    if funcs:
        parts.append('Provides ' + ', '.join(funcs[:4]) + ('.' if len(funcs) <= 4 else ', among other functions.'))
    if not parts and assigns:
        parts.append('Defines module-level names such as ' + ', '.join(assigns[:4]) + '.')
    if not parts:
        parts.append('Part of the Django ' + rel.split('.')[0] + ' package.')
    return ' '.join(parts)

changed = 0
for root in ROOTS:
    for dp, _, fs in os.walk(root):
        for fn in sorted(fs):
            if not fn.endswith('.py'):
                continue
            p = os.path.join(dp, fn)
            src = open(p, encoding='utf-8').read()
            if has_doc(src):
                continue
            d = describe(p, src)
            if d and insert(p, d):
                changed += 1
print('changed', changed)
